import fs from "node:fs"
import path from "node:path"

// tokens/dist/tokens.json is generated by packages/tokens/build.js. Docs read it
// directly, so every value shown here is the value that ships.
export type Token = {
  name: string
  path: string
  type: string
  section: string
  description: string | null
  light: { value: string; literal: string; chain: string[] }
  dark: { value: string; literal: string; chain: string[] }
  tailwind: string[]
}
export type ContrastResult = {
  mode: "light" | "dark"; fg: string; bg: string; min: number; level: "error" | "warn"; ratio: number; pass: boolean
}

const file = path.join(process.cwd(), "..", "..", "tokens", "dist", "tokens.json")

// Reread whenever the file changes, so a token rebuild shows up in the dev
// server without a restart (Next doesn't watch files outside the app).
let cache: { mtime: number; data: { tokens: Token[]; contrast: ContrastResult[] } } | null = null
function load() {
  const mtime = fs.statSync(file).mtimeMs
  if (!cache || cache.mtime !== mtime) cache = { mtime, data: JSON.parse(fs.readFileSync(file, "utf8")) }
  return cache.data
}

export const allTokens = () => load().tokens
export const contrastResults = () => load().contrast
export const bySection = (section: string) => load().tokens.filter((t) => t.section === section)
export const byName = (name: string) => load().tokens.find((t) => t.name === name)

// "color-primary" -> "bg-primary", "radius-md" -> "rounded-md", ...
const PREFIX: [string, string][] = [
  ["color-", "bg-"], ["radius-", "rounded-"], ["shadow-", "shadow-"], ["text-", "text-"],
  ["font-weight-", "font-"], ["font-", "font-"], ["ease-", "ease-"],
]
export function utilityClasses(t: Token) {
  return t.tailwind.filter((k) => !k.includes("--")).map((k) => {
    const [from, to] = PREFIX.find(([p]) => k.startsWith(p)) ?? ["", ""]
    return to + k.slice(from.length)
  })
}
